    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    public static void main(String[] args) {
        check("compress(\"aaabbc\")", "a3b2c1", RunLengthEncoder.compress("aaabbc"));
        check("compress(\"abc\") singles keep a count", "a1b1c1", RunLengthEncoder.compress("abc"));
        check("compress(\"zzzz\") one long run", "z4", RunLengthEncoder.compress("zzzz"));
        check("compress(\"aabaa\") repeated letter in separate runs", "a2b1a2", RunLengthEncoder.compress("aabaa"));
        check("compress(\"q\") single character", "q1", RunLengthEncoder.compress("q"));
        check("compress(\"\") empty string", "", RunLengthEncoder.compress(""));
        check("compress(\"1112\") digits are just characters", "1321", RunLengthEncoder.compress("1112"));
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

